attributes.onChangeText:
{(value) => {
                  setPhone(value);
                  setChallenge(null);
                  setProof(null);
                  setProofExpiry(0);
                  setCode('');
                  if (mode !== 'login') setStep('phone');
                  setError('');
                }}

